// Package entirecli provides helpers for interacting with the parent
// `entire` CLI from inside the entire-sandbox plugin.
//
// The plugin is a separate process exec'd from the entire CLI's
// kubectl-style external-command resolver. It cannot import the parent's
// internal packages, so it discovers configured agents by shelling out to
// `entire agent list` and parsing the marker-prefixed output:
//
//	Agents:
//	  ✓ claude-code
//	    codex
//
// The check-mark prefix denotes "hooks installed for this repo," which is
// the parent CLI's notion of a configured agent.
package entirecli

import (
	"bufio"
	"context"
	"fmt"
	"os/exec"
	"strings"
)

// Agent represents a configured Entire CLI agent.
type Agent struct {
	// Name is the registry key (e.g. "claude-code", "codex").
	Name string
	// Installed is true when the agent has hooks installed in the
	// current repository (a "✓" prefix in the parent CLI's output).
	Installed bool
}

// AgentSpec maps an Entire CLI agent name to the in-VM CLI binary that
// should be launched, plus a human-readable display name.
type AgentSpec struct {
	// EntireName matches Agent.Name (registry key in the parent CLI).
	EntireName string
	// Display is the human-friendly label shown in the picker.
	Display string
	// VMBinary is the command name to invoke inside the VM.
	VMBinary string
	// InstallURL is an optional one-liner installer the plugin can
	// invoke inside the VM if the binary isn't present. Empty means
	// the agent must already be present in the base image.
	InstallURL string
	// InstallerBinDirs are shell PATH entries that an InstallURL may
	// populate outside ~/.local/bin. Entries are emitted into a bash
	// wrapper, so use shell-expanded paths such as "$HOME/.opencode/bin".
	InstallerBinDirs []string
}

// AgentSpecs is the table of agents the plugin knows how to launch in a
// sandbox VM. New rows can be added here as in-VM installers land.
var AgentSpecs = []AgentSpec{
	{
		EntireName: "claude-code",
		Display:    "Claude Code",
		VMBinary:   "claude",
		InstallURL: "https://claude.ai/install.sh",
	},
	{
		EntireName: "codex",
		Display:    "Codex",
		VMBinary:   "codex",
	},
	{
		EntireName: "gemini",
		Display:    "Gemini CLI",
		VMBinary:   "gemini",
	},
	{
		EntireName: "copilot-cli",
		Display:    "Copilot CLI",
		VMBinary:   "copilot",
	},
	{
		EntireName: "cursor",
		Display:    "Cursor",
		VMBinary:   "cursor-agent",
	},
	{
		EntireName: "factoryai-droid",
		Display:    "Factory AI Droid",
		VMBinary:   "droid",
	},
	{
		EntireName:       "opencode",
		Display:          "OpenCode",
		VMBinary:         "opencode",
		InstallURL:       "https://opencode.ai/install",
		InstallerBinDirs: []string{"$HOME/.opencode/bin"},
	},
}

// SpecFor returns the AgentSpec matching name, or zero value + false.
func SpecFor(name string) (AgentSpec, bool) {
	for _, s := range AgentSpecs {
		if s.EntireName == name {
			return s, true
		}
	}
	return AgentSpec{}, false
}

// ListConfigured runs `entire agent list` and returns the agents that
// the parent CLI reports as having hooks installed in the current repo.
//
// On any failure (no `entire` on PATH, command exits non-zero, output is
// unparseable) returns a non-nil error and an empty slice. Callers
// typically fall back to AgentSpecs to offer a sensible default.
func ListConfigured(ctx context.Context) ([]Agent, error) {
	binPath, err := exec.LookPath("entire")
	if err != nil {
		return nil, fmt.Errorf("entire CLI not on PATH: %w", err)
	}
	cmd := exec.CommandContext(ctx, binPath, "agent", "list")
	out, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("entire agent list: %w", err)
	}
	return parseAgentList(string(out))
}

// parseAgentList consumes the textual output of `entire agent list`. The
// format is one agent per line with a two-character prefix: "✓ " when
// hooks are installed, "  " otherwise. A leading "Agents:" header and
// any trailing usage hints are tolerated.
func parseAgentList(s string) ([]Agent, error) {
	var agents []Agent
	scanner := bufio.NewScanner(strings.NewReader(s))
	for scanner.Scan() {
		raw := scanner.Text()
		// Strip the "Agents:" header and any blank/instruction lines
		// that follow. We only consider lines that start with at
		// least one space (the marker prefix is always indented).
		if !strings.HasPrefix(raw, "  ") {
			continue
		}
		line := strings.TrimLeft(raw, " ")
		installed := false
		// The check-mark is encoded as the literal Unicode rune in
		// the parent CLI's output; UTF-8 decoding happens via the
		// strings package below.
		if strings.HasPrefix(line, "✓ ") {
			installed = true
			line = strings.TrimPrefix(line, "✓ ")
		}
		name := strings.TrimSpace(line)
		if name == "" {
			continue
		}
		// Reject lines that look like sentences (e.g. the "No
		// agents installed..." hint). Agent names from the registry
		// are kebab-case identifiers without spaces.
		if strings.ContainsAny(name, " .") {
			continue
		}
		agents = append(agents, Agent{Name: name, Installed: installed})
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("scan agent list: %w", err)
	}
	return agents, nil
}

// ConfiguredSpecs returns AgentSpec entries for agents the parent CLI
// reports as "installed" in the current repository. When the parent CLI
// is unavailable or no agents are installed, returns an empty slice.
func ConfiguredSpecs(ctx context.Context) []AgentSpec {
	agents, err := ListConfigured(ctx)
	if err != nil {
		return nil
	}
	return specsForConfiguredAgents(agents)
}

// ConfiguredSpecsWithError is like ConfiguredSpecs, but distinguishes
// discovery failures from a successful empty agent list.
func ConfiguredSpecsWithError(ctx context.Context) ([]AgentSpec, error) {
	agents, err := ListConfigured(ctx)
	if err != nil {
		return nil, err
	}
	return specsForConfiguredAgents(agents), nil
}

// AllSpecsWithError returns AgentSpec entries for every agent the parent
// CLI knows about, in the order `entire agent list` emits them, plus a
// map indicating which agents are installed (✓ prefix) in the current
// repo. The sandbox setup picker uses this so it can mirror the parent
// CLI's `entire agent` menu: every registered agent is offered, but
// rows for already-installed agents start pre-selected.
//
// Returns an error when `entire agent list` is unavailable; callers
// typically fall back to preserving the on-disk config in that case.
func AllSpecsWithError(ctx context.Context) ([]AgentSpec, map[string]bool, error) {
	agents, err := ListConfigured(ctx)
	if err != nil {
		return nil, nil, err
	}
	installed := make(map[string]bool, len(agents))
	specs := make([]AgentSpec, 0, len(agents))
	for _, a := range agents {
		spec, ok := SpecFor(a.Name)
		if !ok {
			// Unknown agent in the registry — synthesize a best-effort
			// spec so the user can still see and pick it.
			spec = AgentSpec{
				EntireName: a.Name,
				Display:    a.Name,
				VMBinary:   a.Name,
			}
		}
		specs = append(specs, spec)
		installed[a.Name] = a.Installed
	}
	return specs, installed, nil
}

func specsForConfiguredAgents(agents []Agent) []AgentSpec {
	var specs []AgentSpec
	for _, a := range agents {
		if !a.Installed {
			continue
		}
		spec, ok := SpecFor(a.Name)
		if !ok {
			// Unknown agent — synthesize a best-effort spec so the
			// user can still pick it. The VM binary defaults to
			// the Entire name, which works for most CLIs whose
			// command name matches the registry key.
			spec = AgentSpec{
				EntireName: a.Name,
				Display:    a.Name,
				VMBinary:   a.Name,
			}
		}
		specs = append(specs, spec)
	}
	return specs
}

