package cli

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"os"
	"strings"

	"github.com/entireio/entire-sandbox/internal/config"
	"github.com/entireio/entire-sandbox/internal/entirecli"
	"github.com/entireio/entire-sandbox/internal/runtime"
	"github.com/entireio/entire-sandbox/internal/snapshot"
	"github.com/entireio/entire-sandbox/internal/ui"
	"github.com/spf13/cobra"
)

var forceSetup bool
var tmuxSetup bool
var dockerSetup bool
var devcontainerSetup bool

// Mutable for tests; do not call t.Parallel in tests that override these.
var (
	allSpecsForSetup    = entirecli.AllSpecsWithError
	pickSandboxAgentsFn = pickSandboxAgentsInteractive
	offerDockerSetupFn  = offerDockerSetupInteractive
)

var setupCmd = &cobra.Command{
	Use:   "setup",
	Short: "Set up the entire-sandbox runtime environment",
	Long: `Set up the entire-sandbox runtime environment.

Detects the platform-appropriate VM backend and prepares a base image
for sandboxed development:

  macOS / Apple Silicon  Tart (Apple's Virtualization.framework)
  Linux / amd64 or arm64 qemu-system-* + KVM + 9p

Use --docker to select the Docker compatibility backend, or
--devcontainer to use the repo's Dev Containers configuration through
the official devcontainer CLI. On platforms without a native backend,
setup offers Docker automatically when stdin is interactive.

Use --force to tear down existing setup and start fresh.`,
	RunE: func(cmd *cobra.Command, args []string) error {
		return runSetup(cmd.Context(), forceSetup, dockerSetup, devcontainerSetup)
	},
}

func init() {
	setupCmd.Flags().BoolVarP(&forceSetup, "force", "f", false, "Tear down existing setup before reinstalling")
	setupCmd.Flags().BoolVar(&tmuxSetup, "tmux", false, "Run sandbox agents inside tmux")
	setupCmd.Flags().BoolVar(&dockerSetup, "docker", false, "Use Docker compatibility backend instead of the native VM backend")
	setupCmd.Flags().BoolVar(&devcontainerSetup, "devcontainer", false, "Use repo .devcontainer configuration through the Dev Containers CLI")
}

// runSetup performs first-time setup: selects the native, Docker, or
// devcontainer runtime, prepares runtime-side state where applicable,
// best-effort installs enabled agent CLIs when the runtime has a base
// image, and persists the list of agents the user wants pre-installed.
//
// The agent list is seeded from the Entire CLI's configured agents
// (`entire agent list`) when available; this keeps the sandbox aligned
// with the agents the user has already opted into. If no Entire CLI
// agents are detected, setup bakes no agent CLIs into the base VM.
func runSetup(ctx context.Context, force bool, useDocker bool, useDevcontainer bool) error {
	fmt.Println("=== entire-sandbox setup ===")
	fmt.Println()

	cfg, err := config.Load()
	if err != nil {
		cfg = &config.Config{Agents: config.AvailableAgents()}
	}

	specs, installed, listErr := allSpecsForSetup(ctx)
	syncSetupAgents(cfg, specs, installed, listErr)
	if err := pickSandboxAgentsFn(cfg); err != nil {
		return err
	}
	cfg.Tmux = tmuxSetup

	rt, err := selectSetupRuntime(cfg, useDocker, useDevcontainer)
	if err != nil {
		return fmt.Errorf("failed to detect runtime: %w", err)
	}

	if err := cfg.Save(); err != nil {
		fmt.Printf("Warning: failed to save config: %v\n", err)
	}

	fmt.Printf("Detected runtime: %s\n", rt.Name())
	fmt.Println()

	if force {
		fmt.Println("Force flag set, tearing down existing setup...")
		if err := rt.Teardown(ctx); err != nil {
			fmt.Printf("Warning: teardown had issues: %v\n", err)
		}
		// Always clear the snapshot registry on force; the registry
		// is host-side state shared across runtimes.
		if err := snapshot.NewStore().Save(); err != nil {
			fmt.Printf("Warning: failed to clear snapshot state: %v\n", err)
		}
	}

	if !force && rt.IsSetup() {
		if tmuxSetup {
			if err := rt.Setup(ctx, enabledAgentNames(cfg), cfg.Tmux); err != nil {
				return fmt.Errorf("setup failed: %w", err)
			}
			return nil
		}
		fmt.Printf("Runtime '%s' is already configured.\n", rt.Name())
		fmt.Println("Use --force to reinstall.")
		return nil
	}

	if err := rt.Setup(ctx, enabledAgentNames(cfg), cfg.Tmux); err != nil {
		return fmt.Errorf("setup failed: %w", err)
	}

	fmt.Println()
	fmt.Println("Run 'entire sandbox' to launch a configured agent in a sandbox.")
	return nil
}

func selectSetupRuntime(cfg *config.Config, useDocker bool, useDevcontainer bool) (runtime.Runtime, error) {
	if useDocker && useDevcontainer {
		return nil, fmt.Errorf("--docker and --devcontainer are mutually exclusive")
	}
	if useDocker {
		cfg.Runtime = runtime.RuntimeDocker
		return runtime.ByName(runtime.RuntimeDocker)
	}
	if useDevcontainer {
		cfg.Runtime = runtime.RuntimeDevcontainer
		return runtime.ByName(runtime.RuntimeDevcontainer)
	}

	rt, err := runtime.Detect()
	if err == nil {
		cfg.Runtime = rt.Name()
		return rt, nil
	}

	ok, offerErr := offerDockerSetupFn(err)
	if offerErr != nil {
		return nil, offerErr
	}
	if !ok {
		return nil, fmt.Errorf("%w; Docker compatibility mode is available with 'entire sandbox setup --docker'", err)
	}
	cfg.Runtime = runtime.RuntimeDocker
	return runtime.ByName(runtime.RuntimeDocker)
}

func offerDockerSetupInteractive(nativeErr error) (bool, error) {
	fmt.Printf("Native VM backend is unavailable on this platform: %v\n", nativeErr)
	if !isTerminal(os.Stdin) {
		return false, nil
	}
	fmt.Print("Use Docker compatibility backend instead? [Y/n] ")
	line, err := bufio.NewReader(os.Stdin).ReadString('\n')
	if err != nil {
		return false, nil
	}
	switch strings.ToLower(strings.TrimSpace(line)) {
	case "", "y", "yes":
		return true, nil
	default:
		return false, nil
	}
}

func syncSetupAgents(cfg *config.Config, specs []entirecli.AgentSpec, installed map[string]bool, listErr error) {
	if listErr != nil {
		fmt.Printf("Warning: failed to detect Entire CLI agents; preserving existing sandbox agent config: %v\n", listErr)
		fmt.Println()
		return
	}

