// pickAgent prompts the user to choose one of the configured agents.
// When only one agent is configured it auto-selects without prompting,
// since asking would be needless friction. When stdin isn't a TTY
// (piped input, CI), it falls back to the first agent.
func pickAgent(specs []entirecli.AgentSpec) (entirecli.AgentSpec, error) {
	if len(specs) == 0 {
		return entirecli.AgentSpec{}, fmt.Errorf("no agents available")
	}
	if len(specs) == 1 {
		fmt.Printf("Launching the only configured agent: %s\n", specs[0].Display)
		return specs[0], nil
	}

	if !isTerminal(os.Stdin) {
		fmt.Printf("Non-interactive stdin; defaulting to %s\n", specs[0].Display)
		return specs[0], nil
	}

	fmt.Println("Configured Entire CLI agents:")
	for i, spec := range specs {
		fmt.Printf("  %d) %s (%s)\n", i+1, spec.Display, spec.EntireName)
	}
	fmt.Println()
	fmt.Print("Pick an agent [1]: ")

	reader := bufio.NewReader(os.Stdin)
	input, _ := reader.ReadString('\n')
	input = strings.TrimSpace(input)

	if input == "" {
		return specs[0], nil
	}

	// Accept either the 1-based index or the agent name (display or
	// registry key) so users can `echo claude-code | entire sandbox`.
	if n, err := strconv.Atoi(input); err == nil {
		if n < 1 || n > len(specs) {
			return entirecli.AgentSpec{}, fmt.Errorf("choice %d out of range (1-%d)", n, len(specs))
		}
		return specs[n-1], nil
	}
	for _, spec := range specs {
		if strings.EqualFold(input, spec.EntireName) || strings.EqualFold(input, spec.Display) {
			return spec, nil
		}
	}
	return entirecli.AgentSpec{}, fmt.Errorf("unknown agent: %s", input)
}

// isTerminal returns true when f is connected to a TTY. We can't
// import golang.org/x/term without a new dep, so use the file-mode
// fallback that works on macOS/Linux: a character device is a TTY.
func isTerminal(f *os.File) bool {
	info, err := f.Stat()
	if err != nil {
		return false
	}
	return info.Mode()&os.ModeCharDevice != 0
}

// runAgentInSandbox is the unified launcher used by both `run <agent>`
// and the interactive default. It mirrors ferrata's runClaude flow but
// takes the agent identity (binary name and any in-VM installer URL)
// as a parameter so any registered agent can be launched.
//
// Steps:
//  1. Resolve the repo path on the host.
//  2. Detect the runtime; bail with a friendly hint if `setup` hasn't run.
//  3. Persist the agent as enabled in the local config (the same
//     auto-enable behavior ferrata had for Claude).
//  4. Register a session in the state store and arrange cleanup.
//  5. Build the mount list (always include the agent's host config dir
//     when one is conventionally placed under ~/.<name>).
//  6. Use a snapshot VM if the repo has a setup script and a matching
//     snapshot exists; otherwise clone the base.
//  7. Start the VM and launch the agent over SSH+tmux. If the binary
//     isn't present, install it via the spec's InstallURL first.
func runAgentInSandbox(ctx context.Context, path string, spec entirecli.AgentSpec, agentArgs []string, fresh bool) error {
	absPath, err := filepath.Abs(path)
	if err != nil {
		return fmt.Errorf("failed to resolve path: %w", err)
	}

	cfg, _ := config.Load()
	rt, err := configuredRuntime(cfg)
	if err != nil {
		return fmt.Errorf("failed to detect runtime: %w", err)
	}

	if !rt.IsSetup() {
		return fmt.Errorf("runtime not configured; run 'entire sandbox setup' first")
	}

	enableAgent(cfg, spec)
	_ = cfg.Save()

	session := sandbox.NewSession(absPath, rt.Name())
	fmt.Printf("Starting %s sandbox for %s...\n", spec.Display, absPath)

	stagingDir := filepath.Join(os.TempDir(), "entire-sandbox-agent-config-"+session.ID)
	cleanup := func() {
		fmt.Println()
		fmt.Println("Cleaning up...")
		sandbox.Cleanup(ctx, session, rt)
		_ = os.RemoveAll(stagingDir)
	}

	setupSignalHandler(cleanup)

	store := loadOrCreateStore()
	store.AddSession(session)
	if err := store.Save(); err != nil {
		fmt.Printf("Warning: failed to save session state: %v\n", err)
	}

	mounts, err := agentMountsWithStaging(spec, stagingDir)
	if err != nil {
		cleanup()
		return err
	}

