// MultiSelectItem is a single row in a MultiSelect prompt.
type MultiSelectItem struct {
	// Label is the human-readable text shown next to the checkbox.
	Label string
	// Selected is the initial checked state and is updated in place
	// when the user toggles the row.
	Selected bool
}

// ErrMultiSelectCanceled is returned from MultiSelect when the user
// aborts the prompt with Ctrl+C or Esc.
var ErrMultiSelectCanceled = errors.New("multiselect canceled")

// MultiSelect renders an interactive multi-select prompt using the same
// huh-based Dracula theme as the parent `entire agent` command, so the
// sandbox plugin's setup screen visually matches the rest of the Entire
// CLI. Items are returned with their Selected fields updated.
func MultiSelect(title, hint string, items []MultiSelectItem) ([]MultiSelectItem, error) {
	if len(items) == 0 {
		return items, nil
	}

	options := make([]huh.Option[int], 0, len(items))
	for i, item := range items {
		options = append(options, huh.NewOption(item.Label, i).Selected(item.Selected))
	}

	var selected []int
	// Add 2 rows of slack for the title/description block so huh's
	// viewport doesn't clip the option list. Without this huh defaults
	// to a 10-row viewport that hides options behind a scroll affordance
	// even when the screen has plenty of room.
	height := len(options) + 2
	form := huh.NewForm(
		huh.NewGroup(
			huh.NewMultiSelect[int]().
				Title(title).
				Description(hint).
				Options(options...).
				Height(height).
				Value(&selected),
		),
	).WithTheme(huh.ThemeFunc(huh.ThemeDracula))

	if err := form.Run(); err != nil {
		if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, huh.ErrTimeout) {
			return items, ErrMultiSelectCanceled
		}
		return items, fmt.Errorf("multiselect prompt: %w", err)
	}

	result := make([]MultiSelectItem, len(items))
	copy(result, items)
	for i := range result {
		result[i].Selected = false
	}
	for _, idx := range selected {
		if idx >= 0 && idx < len(result) {
			result[idx].Selected = true
		}
	}
	return result, nil
}

